-- Additive Student fee frequency and fee component masters.
-- Apply to the Skolenza database before deploying the matching API.
-- No fee structures, benefit schemes, invoices, payments or Angular UI are created here.

BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeFrequencyMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TemplateSourceId" bigint,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500),
    "InstallmentsPerYear" smallint NOT NULL,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint,
    "DeletedDateTime" timestamp,
    CONSTRAINT "FK_StudentFeeFrequencyMaster_Institution"
        FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeFrequencyMaster_InstallmentsPerYear"
        CHECK ("InstallmentsPerYear" BETWEEN 1 AND 12)
);

ALTER TABLE skolenza."StudentFeeFrequencyMaster"
    ALTER COLUMN "Id" TYPE bigint USING "Id"::bigint,
    ALTER COLUMN "TemplateSourceId" TYPE bigint USING "TemplateSourceId"::bigint;

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeFrequencyMaster_Institution_Code"
    ON skolenza."StudentFeeFrequencyMaster" ("InstitutionId", upper("Code"))
    WHERE NOT "IsSoftDeleted";

CREATE INDEX IF NOT EXISTS "IX_StudentFeeFrequencyMaster_List"
    ON skolenza."StudentFeeFrequencyMaster" ("InstitutionId", "IsActive", "DisplayOrder", "InstallmentsPerYear")
    WHERE NOT "IsSoftDeleted";

CREATE TABLE IF NOT EXISTS skolenza."StudentFeeComponentMaster" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "TemplateSourceId" bigint,
    "Code" varchar(60) NOT NULL,
    "Name" varchar(150) NOT NULL,
    "Description" varchar(500),
    "ChargeNature" smallint NOT NULL,
    "DisplayOrder" smallint NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "IsSystemDefined" boolean NOT NULL DEFAULT false,
    "AddedById" bigint,
    "AddedDateTime" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedById" bigint,
    "UpdatedDateTime" timestamp,
    "IsSoftDeleted" boolean NOT NULL DEFAULT false,
    "SoftDeletedById" bigint,
    "DeletedDateTime" timestamp,
    CONSTRAINT "FK_StudentFeeComponentMaster_Institution"
        FOREIGN KEY ("InstitutionId") REFERENCES skolenza."Institution"("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_StudentFeeComponentMaster_ChargeNature"
        CHECK ("ChargeNature" IN (1, 2))
);

ALTER TABLE skolenza."StudentFeeComponentMaster"
    ALTER COLUMN "Id" TYPE bigint USING "Id"::bigint,
    ALTER COLUMN "TemplateSourceId" TYPE bigint USING "TemplateSourceId"::bigint;

CREATE UNIQUE INDEX IF NOT EXISTS "UX_StudentFeeComponentMaster_Institution_Code"
    ON skolenza."StudentFeeComponentMaster" ("InstitutionId", upper("Code"))
    WHERE NOT "IsSoftDeleted";

CREATE INDEX IF NOT EXISTS "IX_StudentFeeComponentMaster_List"
    ON skolenza."StudentFeeComponentMaster" ("InstitutionId", "ChargeNature", "IsActive", "DisplayOrder")
    WHERE NOT "IsSoftDeleted";

INSERT INTO skolenza."Module"
    ("InstitutionId", "ModuleCode", "ModuleName", "DisplayName", "URLPath", "ParentModuleId", "IsLeafNode",
     "IsModuleDisplayInUI", "IsCommonMenu", "IsActive", "ImageIconWeb", "ImageIconMobile", "ItemPriority",
     "Remark", "AddedById", "AddedDateTime", "ModuleScope")
SELECT NULL, 'STUDENT_FEES', 'Student-Fees', 'Student Fees', '/app/student-fees', NULL, TRUE,
       TRUE, FALSE, TRUE, 'bi bi-cash-coin', 'payments', 580,
       'Student fee component and payment-frequency masters and fee operations.', 1, CURRENT_TIMESTAMP, 1
WHERE NOT EXISTS (SELECT 1 FROM skolenza."Module" WHERE "ModuleCode" = 'STUDENT_FEES');

INSERT INTO skolenza."ModuleOperationMapping"
    ("ModuleId", "OperationId", "PageURL", "IconURL", "IsCommonItem", "IsOperational", "Priority", "Remark",
     "IsActive", "AddedById", "AddedDateTime")
SELECT module."Id", operation."Id", module."URLPath", module."ImageIconWeb", FALSE, TRUE,
       CASE lower(btrim(operation."OperationName"))
           WHEN 'view' THEN 10 WHEN 'add' THEN 20 WHEN 'update' THEN 30 WHEN 'delete' THEN 40 ELSE 99 END,
       'Student fee master API permission.', TRUE, 1, CURRENT_TIMESTAMP
FROM skolenza."Module" module
CROSS JOIN skolenza."Operation" operation
WHERE module."ModuleCode" = 'STUDENT_FEES'
  AND lower(btrim(operation."OperationName")) IN ('view', 'add', 'update', 'delete')
  AND operation."IsActive"
  AND NOT EXISTS (
      SELECT 1 FROM skolenza."ModuleOperationMapping" existing
      WHERE existing."ModuleId" = module."Id" AND existing."OperationId" = operation."Id"
  );

COMMIT;
